const event = $input.first().json;

// Line Messaging Trigger ปลดปีก body.events ให้แล้ว event มาตรง ๆ ใน json
// สนใจเฉพาะข้อความตัวอักษร ข้าม sticker/รูปภาพ/อื่น ๆ ใน demo นี้
if (event.message?.type !== 'text') {
  return [];
}

return [{
  json: {
    replyToken: event.replyToken,
    userId: event.source?.userId,
    userText: event.message.text
  }
}];

const items = $input.all();
const records = items.map(i => i.json);
const userText = $('แยกข้อมูลจาก LINE Event').first().json.userText;

// ชื่อหัวข้อของข้อสอบ 10 ข้อ (เรียงตามลำดับเดียวกับ Workshop 2 "Calculate Score")
// แก้ไขรายการนี้ให้ตรงกับข้อสอบจริง ถ้าเปลี่ยนชุดคำถามใน Workshop 2
const TOPICS = [
  'หน่วยพื้นฐานของสิ่งมีชีวิต (เซลล์)',
  'วัตถุดิบในการสังเคราะห์ด้วยแสง',
  'จุดเดือดของน้ำบริสุทธิ์',
  'ไมโทคอนเดรีย (Powerhouse of the Cell)',
  'นิวเคลียส',
  'ผนังเซลล์',
  'กระบวนการสังเคราะห์ด้วยแสง',
  'สิ่งมีชีวิตเซลล์เดียว',
  'ระดับการจัดระเบียบของสิ่งมีชีวิต',
  'การหายใจระดับเซลล์ (Cellular Respiration)'
];

if (records.length === 0) {
  return [{
    json: {
      userText,
      formatted_data_string: '[]',
      stats_summary: 'ยังไม่มีข้อมูลผลสอบในระบบ'
    }
  }];
}

const totalStudents = records.length;
const avgPercentage = records.reduce((s, r) => s + Number(r.percentage || 0), 0) / totalStudents;
const maxPercentage = Math.max(...records.map(r => Number(r.percentage || 0)));
const minPercentage = Math.min(...records.map(r => Number(r.percentage || 0)));
const passCount = records.filter(r => r.pass_status === 'ผ่าน').length;
const passRate = (passCount / totalStudents) * 100;

// อัตราตอบผิดรายข้อ เพื่อชี้จุดที่ควรทบทวน/ปรับปรุงการสอนเพิ่ม
const wrongRatePerQuestion = [];
for (let q = 1; q <= 10; q++) {
  const key = `is_correct_${q}`;
  const withData = records.filter(r => r[key] !== undefined && r[key] !== '' && r[key] !== null);
  if (withData.length === 0) continue;
  const wrongCount = withData.filter(r => r[key] === false || r[key] === 'false').length;
  wrongRatePerQuestion.push({
    question: q,
    topic: TOPICS[q - 1] || `ข้อ ${q}`,
    wrong_rate_percent: Math.round((wrongCount / withData.length) * 100)
  });
}
wrongRatePerQuestion.sort((a, b) => b.wrong_rate_percent - a.wrong_rate_percent);

const statsSummary = {
  total_students: totalStudents,
  avg_percentage: Math.round(avgPercentage * 10) / 10,
  max_percentage: maxPercentage,
  min_percentage: minPercentage,
  pass_count: passCount,
  pass_rate_percent: Math.round(passRate * 10) / 10,
  wrong_rate_per_question_sorted_desc: wrongRatePerQuestion
};

return [{
  json: {
    userText,
    formatted_data_string: JSON.stringify(records, null, 2),
    stats_summary: JSON.stringify(statsSummary, null, 2)
  }
}];

const replyToken = $('แยกข้อมูลจาก LINE Event').first().json.replyToken;
const replyText = $json.output;

return [{
  json: {
    replyToken,
    replyText
  }
}];
